import{_ as a,c as i,o as e,a9 as n}from"./chunks/framework.BXLNC15u.js";const k=JSON.parse('{"title":"Project Setup","description":"Create a new PURISTA project and scaffold service artifacts","frontmatter":{"title":"Project Setup","description":"Create a new PURISTA project and scaffold service artifacts","order":101000},"headers":[],"relativePath":"handbook/1_quickstart/setup-the-purista-project.md","filePath":"handbook/1_quickstart/setup-the-purista-project.md","lastUpdated":1778836103000}'),t={name:"handbook/1_quickstart/setup-the-purista-project.md"};function l(p,s,r,d,o,h){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="setup-a-purista-project" tabindex="-1">Setup a PURISTA project <a class="header-anchor" href="#setup-a-purista-project" aria-label="Permalink to “Setup a PURISTA project”">​</a></h1><p>In this quickstart step, you create a new project with the PURISTA CLI blueprint engine. The generator resolves a local project blueprint based on your runtime, event bridge, HTTP server, linting, and module-format choices, then writes a coherent project skeleton for that setup.</p><h2 id="create-a-new-project" tabindex="-1">Create a new project <a class="header-anchor" href="#create-a-new-project" aria-label="Permalink to “Create a new project”">​</a></h2><p>Run one of the following commands:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-12" id="tab-13" checked><label data-title="npm" for="tab-13">npm</label><input type="radio" name="group-12" id="tab-14"><label data-title="bun" for="tab-14">bun</label><input type="radio" name="group-12" id="tab-15"><label data-title="yarn" for="tab-15">yarn</label><input type="radio" name="group-12" id="tab-16"><label data-title="pnpm" for="tab-16">pnpm</label></div><div class="blocks"><div class="language-bash active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purista@latest</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purista@latest</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purista@latest</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purista@latest</span></span></code></pre></div></div></div><p>You can also run the same flow directly through the main CLI:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">purista</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>For CI, scripts, or agentic tooling, the same command also supports deterministic non-interactive usage:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">purista</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --event-bridge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --webserver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --linter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> biome</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --formatter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> biome</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --package-manager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --non-interactive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --no-install</span></span></code></pre></div><p>The create wrapper and the main CLI use the same underlying command engine, so both entry points generate the same project shape.</p><p>Choose the options that fit your runtime and deployment setup:</p><ul><li><code>runtime</code>: <code>node</code> or <code>bun</code></li><li><code>event bridge</code>: <code>default</code>, <code>amqp</code>, <code>mqtt</code>, <code>nats</code>, or <code>dapr</code></li><li><code>webserver</code>: add the bundled Hono-based HTTP surface when needed</li><li><code>linter</code>: <code>biome</code>, <code>eslint</code>, or <code>none</code></li><li><code>module type</code>: <code>module</code> or <code>commonjs</code></li></ul><p>After setup, generate services and business artifacts with the CLI:</p><ol><li><code>purista add service</code></li><li><code>purista add command</code></li><li><code>purista add subscription</code></li><li><code>purista add stream</code></li><li><code>purista add queue</code></li><li><code>purista add queue-worker</code></li><li><code>purista add agent</code></li></ol><p>Recommended scaffold order for new projects:</p><ol><li><code>purista add service</code> and first <code>purista add command</code></li><li><code>purista add stream</code> if you need push/live updates</li><li><code>purista add queue</code> + <code>purista add queue-worker</code> for background jobs</li><li><code>purista add agent</code> when a capability is model-driven, conversational, or tool-loop oriented</li></ol><p>Rule of thumb:</p><ul><li>commands = request/response entrypoints</li><li>streams = live outbound updates</li><li>queues/workers = durable async processing</li><li>agents = core PURISTA primitives backed by <code>@purista/harness</code></li></ul><p>See also:</p><ul><li><a href="./../2_building_business-logic/stream/">Streams</a></li><li><a href="./../2_building_business-logic/queue/">Queues</a></li></ul><p>Agents are available from <code>@purista/core</code>. Core stays provider-neutral; install a provider package only in applications that bind live models at runtime:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-167" id="tab-168" checked><label data-title="npm" for="tab-168">npm</label><input type="radio" name="group-167" id="tab-169"><label data-title="pnpm" for="tab-169">pnpm</label><input type="radio" name="group-167" id="tab-170"><label data-title="bun" for="tab-170">bun</label><input type="radio" name="group-167" id="tab-171"><label data-title="yarn" for="tab-171">yarn</label></div><div class="blocks"><div class="language-bash active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @purista/harness-openai</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @purista/harness-openai</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @purista/harness-openai</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @purista/harness-openai</span></span></code></pre></div></div></div><h2 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to “Project structure”">​</a></h2><p>The generated app shape is intentionally minimal. The initializer creates the runtime/bootstrap files, the project config, and an example <code>ping</code> service with one starter command. Follow-up CLI commands then extend that structure.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>|-public/                     # only when --webserver is enabled</span></span>
<span class="line"><span>|-src/</span></span>
<span class="line"><span>| |-config/                   # bridge/http config files when required by the selected blueprints</span></span>
<span class="line"><span>| |-agents/</span></span>
<span class="line"><span>| |-service/</span></span>
<span class="line"><span>| |   |- serviceEvent.enum.ts</span></span>
<span class="line"><span>| |   |- ping/</span></span>
<span class="line"><span>| |       |- generalPingServiceInfo.ts</span></span>
<span class="line"><span>| |       |- v1/</span></span>
<span class="line"><span>| |           |- pingServiceConfig.ts</span></span>
<span class="line"><span>| |           |- pingV1ServiceBuilder.ts</span></span>
<span class="line"><span>| |           |- pingV1Service.ts</span></span>
<span class="line"><span>| |           |- pingV1Service.test.ts</span></span>
<span class="line"><span>| |           |- command/</span></span>
<span class="line"><span>| |               |- ping/</span></span>
<span class="line"><span>| |                   |- schema.ts</span></span>
<span class="line"><span>| |                   |- types.ts</span></span>
<span class="line"><span>| |                   |- pingCommandBuilder.ts</span></span>
<span class="line"><span>| |                   |- pingCommandBuilder.test.ts</span></span>
<span class="line"><span>| |-eventbridge.ts</span></span>
<span class="line"><span>| |-http.ts                   # only when --webserver is enabled</span></span>
<span class="line"><span>| |-index.ts</span></span>
<span class="line"><span>|- package.json</span></span>
<span class="line"><span>|- package-lock.json / bun.lockb / pnpm-lock.yaml / yarn.lock</span></span>
<span class="line"><span>|- tsconfig.json</span></span>
<span class="line"><span>|- purista.json</span></span>
<span class="line"><span>|- README.md</span></span>
<span class="line"><span>|- .gitignore</span></span></code></pre></div><p>Notes:</p><ul><li><code>src/service</code> and <code>src/agents</code> are the default CLI-managed roots.</li><li>The exact filenames follow the <code>fileConvention</code> and <code>eventConvention</code> from <code>purista.json</code>.</li><li><code>src/eventbridge.ts</code> is generated from the chosen bridge blueprint.</li><li><code>src/http.ts</code> and <code>public/</code> are only created for the HTTP-enabled project variants.</li><li>Additional commands, subscriptions, streams, queues, queue workers, and agents are generated into this structure by <code>purista add ...</code>.</li></ul><p>The CLI expects this structure for automated updates and type-safe wiring, so avoid moving the generated roots unless you also update <code>purista.json</code>.</p>`,28)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
